import{_ as e,o,c as a,a2 as r}from"./chunks/framework.Dg5D4OHa.js";const h=JSON.parse('{"title":"central migrate cosmos-copy","description":"","frontmatter":{},"headers":[],"relativePath":"commands/migrate-cosmos-copy.md","filePath":"commands/migrate-cosmos-copy.md"}'),d={name:"commands/migrate-cosmos-copy.md"};function s(n,t,c,i,l,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="central-migrate-cosmos-copy" tabindex="-1">central migrate cosmos-copy <a class="header-anchor" href="#central-migrate-cosmos-copy" aria-label="Permalink to &quot;central migrate cosmos-copy&quot;">​</a></h1><p>Copy one Cosmos database into another, verbatim (system fields excluded).</p><p>A cutover runs the modes in order: copy online, days ahead; records each container&#39;s _ts mark to --marks-file delta copies documents changed since the marks and moves them forward; run once ahead of the write freeze to shrink it, then again inside it reconcile in the write freeze; deletes target documents no longer in the source (hard deletes) verify in the write freeze; counts must match exactly, plus a parity sample</p><p>Any 429 that survives the SDK&#39;s retries stops the whole run. Exit code 1 on any failed container. A failed or interrupted copy records no mark for that container; re-run copy with --containers for it. Copied documents get a new _ts, so a TTL container&#39;s expiry clock restarts on the target. Source and target may be the same database only with --dry-run (read-only validation).</p><p>Example: central migrate cosmos-copy --source-connection-string &quot;AccountEndpoint=...&quot; <br> --source-database CentralDatabase --target-database CentralDatabase2 <br> --mode copy --marks-file marks.json --source-ru-per-second 400 --target-ru-per-second 4000</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>central migrate cosmos-copy [options]</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><code>--source-connection-string &lt;String&gt;</code></td><td>Source Cosmos account connection string.</td><td>Yes</td></tr><tr><td><code>--source-database &lt;String&gt;</code></td><td>Source database name.</td><td>Yes</td></tr><tr><td><code>--target-connection-string &lt;String&gt;</code></td><td>Target Cosmos account connection string. Defaults to the source&#39;s (same account).</td><td>No</td></tr><tr><td><code>--target-database &lt;String&gt;</code></td><td>Target database name. Its containers must already exist with the source&#39;s partition key path, version and TTL.</td><td>Yes</td></tr><tr><td><code>--mode &lt;CosmosCopyMode&gt;</code></td><td>copy (online, records marks) | delta (changes since the marks; moves them forward) | reconcile (delete target docs gone from the source) | verify (exact counts + parity sample).</td><td>Yes</td></tr><tr><td><code>--marks-file &lt;FileInfo&gt;</code></td><td>JSON file of per-container _ts marks. copy and delta set a mark per fully copied container (keeping the others); delta reads it first.</td><td>No</td></tr><tr><td><code>--containers &lt;String[]&gt;</code></td><td>Restrict to these containers (space- or comma-separated). Default: every source container.</td><td>No</td></tr><tr><td><code>--batch-size &lt;Int32&gt;</code></td><td>Documents per page and per write batch.</td><td>No</td></tr><tr><td><code>--source-ru-per-second &lt;Double&gt;</code></td><td>Average RU/s cap for reads on the source. 0 = uncapped.</td><td>No</td></tr><tr><td><code>--target-ru-per-second &lt;Double&gt;</code></td><td>Average RU/s cap for writes, deletes and reads on the target. 0 = uncapped.</td><td>No</td></tr><tr><td><code>--parity-sample &lt;Int32&gt;</code></td><td>verify: documents per container to compare field by field (system fields ignored).</td><td>No</td></tr><tr><td><code>--dry-run</code></td><td>Read and count only; write nothing to the target or the marks file.</td><td>No</td></tr></tbody></table>',9)])])}const u=e(d,[["render",s]]);export{h as __pageData,u as default};
